import time

def execute_with_retry():
    retries = 3
    for i in range(retries):
        try:
            print("Executing task...")
            return True
        except Exception:
            print(f"Retry {i+1}")
            time.sleep(1)
    return False

if __name__ == "__main__":
    execute_with_retry()

